reg [1:0] state, next_state;

parameter IDLE = 2'd0,
          WORK = 2'd1;

always @(*) begin
    case (state)
        IDLE: next_state = x ? WORK : IDLE;
        WORK: next_state = IDLE;
        default: next_state = IDLE;
    endcase
end

always @(posedge clk or negedge aresetn) begin
    if (!aresetn) begin
        state <= IDLE;
        z <= 0;
    end else begin
        state <= next_state;
        case (state)
            IDLE: z <= 0;
            WORK: z <= 1;
        endcase
    end
end

endmodule

reg [1:0] state, next_state;

parameter IDLE = 2'd0,
          ONE = 2'd1,
          ZERO = 2'd2;

always @ (posedge clk or posedge reset)
    if (reset)
        state <= IDLE;
    else
        state <= next_state;

always @ (*)
    case (state)
        IDLE:
            if (in)
                next_state = ONE;
            else
                next_state = ZERO;
        ONE:
            if (in)
                next_state = ONE;
            else
                next_state = ZERO;
        ZERO:
            if (in)
                next_state = ONE;
            else
                next_state = ZERO;
    endcase

assign out = (state == ONE);

endmodule

